// ── System health cache (refreshes every 5s server-side) ────────
interface HealthEntry {
  service: string
  status: string
  latencyMs: number
  checks: { database: string; redis: string; outbox: string }
  uptime: number
  lastChecked: string
}
let healthCache: HealthEntry[] = []

async function fetchAllHealth(): Promise<HealthEntry[]> {
  const serviceUrls: Record<string, string> = {
    auth: env.AUTH_SERVICE_URL,
    finance: env.FINANCE_SERVICE_URL,
    inventory: env.INVENTORY_SERVICE_URL,
    hr: env.HR_SERVICE_URL,
    projects: env.PROJECTS_SERVICE_URL,
    rental: env.RENTAL_SERVICE_URL,
    notifications: env.NOTIFICATIONS_SERVICE_URL,
    reporting: env.REPORTING_SERVICE_URL,
    gateway: `http://localhost:${process.env.PORT ?? 3000}`,
  }
  return Promise.all(
    Object.entries(serviceUrls).map(async ([name, baseUrl]) => {
      const start = Date.now()
      try {
        const res = await fetch(`${baseUrl}/health`, { signal: AbortSignal.timeout(3000) })
        const latencyMs = Date.now() - start
        const body = res.ok ? ((await res.json()) as Record<string, unknown>) : {}
        const checks = (body.checks as Record<string, unknown>) ?? {}
        const getStatus = (c: unknown) => {
          if (typeof c === 'object' && c !== null && 'status' in c)
            return String((c as Record<string, unknown>).status)
          return typeof c === 'string' ? c : 'ok'
        }
        return {
          service: name,
          status: res.ok
            ? String(body.status ?? 'ok')
                .replace('ok', 'healthy')
                .replace('down', 'unhealthy')
            : 'unhealthy',
          latencyMs,
          checks: {
            database: getStatus(checks.database) || 'ok',
            redis: getStatus(checks.redis) || 'ok',
            outbox: getStatus(checks.outbox) || 'ok',
          },
          uptime: typeof body.uptime === 'number' ? body.uptime : 0,
          lastChecked: new Date().toISOString(),
        }
      } catch {
        return {
          service: name,
          status: 'unhealthy',
          latencyMs: Date.now() - start,
          checks: { database: 'error', redis: 'error', outbox: 'error' },
          uptime: 0,
          lastChecked: new Date().toISOString(),
        }
      }
    }),
  )
}

// Warm cache immediately, then refresh every 5s
fetchAllHealth()
  .then((r) => {
    healthCache = r
  })
  .catch(() => null)
setInterval(async () => {
  try {
    healthCache = await fetchAllHealth()
  } catch {
    /* keep stale cache */
  }
}, 10000)

// ── PO lifecycle helpers ────────────────────────────────────────

interface GWAuth {
  userId: string
  companyId: string
  role: string
}

interface EditChanges {
  header?: Record<string, { from: unknown; to: unknown }>
  lines?: {
    edited?: { id: string; field: string; from?: unknown; to: unknown }[]
    added?: Record<string, unknown>[]
    removed?: string[]
  }
}

function buildEditChangeSummary(changes: EditChanges): string {
  const parts: string[] = []
  const headerFields = Object.keys(changes.header ?? {})
  if (headerFields.length > 0) {
    const details = headerFields.map((f) => {
      const diff = changes.header![f]
      return `${f}: "${diff.from ?? '—'}" → "${diff.to ?? '—'}"`
    })
    parts.push(`Header: ${details.join(', ')}`)
  }
  const edited = changes.lines?.edited ?? []
  const added = changes.lines?.added ?? []
  const removed = changes.lines?.removed ?? []
  if (edited.length > 0) {
    const editDetails = edited.map((e) => `${e.field}: "${e.from ?? '—'}" → "${e.to ?? '—'}"`)
    parts.push(`Lines edited (${edited.length}): ${editDetails.join(', ')}`)
  }
  if (added.length > 0) parts.push(`Lines added: ${added.length}`)
  if (removed.length > 0) parts.push(`Lines removed: ${removed.length}`)
  return parts.join(' | ')
}

// A PO is editable directly (no edit-request approval needed) up until it's been
// approved — the state machine has no transition back from these statuses to an
// earlier stage, so this is a reliable, one-way gate. 'ready_to_issue' is included
// because 100%-stock-covered POs skip 'approved' entirely (inventory_check →
// ready_to_issue → completed via approve_stock_issuance) — that transition is
// itself the approval for that fast path.
//
// 'cancelled' is included too even though it's reachable from both pre- and
// post-approval statuses (CANCELLABLE covers everything from 'draft' onward) —
// the current status alone can't tell those two cases apart, so this errs
// conservative and keeps requiring approval rather than risk silently
// auto-applying an edit to a PO that actually had been approved before it was
// cancelled.
const POST_APPROVAL_PO_STATUSES = [
  'approved',
  'ready_to_issue',
  'items_bought',
  'goods_received',
  'finance_audit',
  'invoiced',
  'completed',
  'cancelled',
]

async function applyPOEditChanges(
  client: PoolClient,
  poId: string,
  changes: EditChanges,
): Promise<void> {
  const allowed = [
    'notes',
    'expected_delivery_date',
    'vendor_id',
    'analytic_account_id',
    'currency_code',
  ]
  if (changes.header && Object.keys(changes.header).length > 0) {
    const sets: string[] = []
    const vals: unknown[] = []
    for (const [field, diff] of Object.entries(changes.header)) {
      if (!allowed.includes(field)) continue
      sets.push(`${field}=$${vals.length + 1}`)
      vals.push(diff.to)
    }
    if (sets.length > 0) {
      vals.push(poId)
      await client.query(
        `UPDATE purchase_orders SET ${sets.join(',')},updated_at=NOW() WHERE id=$${vals.length}`,
        vals,
      )
    }
  }
  const lineAllowed = ['description', 'qty_ordered', 'unit_price', 'uom', 'product_id']
  const priceAffectedLineIds = new Set<string>()
  for (const e of changes.lines?.edited ?? []) {
    if (!lineAllowed.includes(e.field)) continue
    await client.query(`UPDATE po_lines SET ${e.field}=$1 WHERE id=$2 AND po_id=$3`, [
      e.to,
      e.id,
      poId,
    ])
    if (e.field === 'qty_ordered' || e.field === 'unit_price') priceAffectedLineIds.add(e.id)
  }
  // qty_ordered/unit_price above only ever touch their own single column —
  // total_price (and the PO-level totals derived from it further down) was
  // never recalculated after an edit changed either one, so the printed PO
  // and every other total_price consumer kept showing the pre-edit amount.
  // Same zeroing rule as confirmPOInventoryCheck: a line fully covered from
  // stock still contributes $0 regardless of what its price/qty now say.
  if (priceAffectedLineIds.size > 0) {
    await client.query(
      `UPDATE po_lines
       SET total_price = CASE WHEN qty_from_stock >= qty_ordered THEN 0 ELSE qty_ordered * unit_price END
       WHERE id = ANY($1) AND po_id = $2`,
      [Array.from(priceAffectedLineIds), poId],
    )
  }
  if ((changes.lines?.added ?? []).length > 0) {
    const poRes = await client.query<{ company_id: string; base_currency_code: string }>(
      `SELECT company_id, base_currency_code FROM purchase_orders WHERE id=$1`,
      [poId],
    )
    const companyId = poRes.rows[0]!.company_id
    const baseCurrencyCode = poRes.rows[0]!.base_currency_code
    for (const line of changes.lines?.added ?? []) {
      // The frontend's added-line draft shape uses `qty` (matching the form
      // field name), not `qty_ordered` (the po_lines column name used for
      // *edited* lines' `field` value) — reading the wrong key here always
      // produced qty=0, which then failed po_lines' CHECK (qty_ordered > 0)
      // on insert. The whole edit request submission was silently lost
      // since the frontend's mutation call has no onError handler.
      const qty = Number(line.qty ?? 0),
        price = Number(line.unit_price ?? 0)
      const currencyCode = (line.currency_code as string | undefined) ?? baseCurrencyCode
      const fxRateToBase = await resolveFxRateToBase(client, companyId, currencyCode, baseCurrencyCode)
      await client.query(
        `INSERT INTO po_lines (po_id,line_number,description,product_id,qty_ordered,unit_price,initial_unit_price,currency_code,fx_rate_to_base,uom,total_price)
         VALUES ($1,(SELECT COALESCE(MAX(line_number),0)+1 FROM po_lines WHERE po_id=$1),$2,$3,$4,$5,$5,$6,$7,$8,$9)`,
        [
          poId,
          line.description,
          line.product_id ?? null,
          qty,
          price,
          currencyCode,
          fxRateToBase,
          line.uom ?? 'unit',
          qty * price,
        ],
      )
    }
  }
  for (const lineId of changes.lines?.removed ?? []) {
    await client.query(`DELETE FROM po_lines WHERE id=$1 AND po_id=$2`, [lineId, poId])
  }
  if (changes.lines) {
    // Converted the same way as recalcPO — see that function's comment.
    await client.query(
      `UPDATE purchase_orders
       SET subtotal=(SELECT COALESCE(SUM(total_price * COALESCE(fx_rate_to_base,1)),0) FROM po_lines WHERE po_id=$1),
           total_amount=(SELECT COALESCE(SUM(total_price * COALESCE(fx_rate_to_base,1)),0) FROM po_lines WHERE po_id=$1),
           updated_at=NOW()
       WHERE id=$1`,
      [poId],
    )
  }
}

async function poTransition(
  client: import('@fnc-erp/db').PoolClient,
  poId: string,
  fromStatus: POStatus,
  toStatus: POStatus,
  action: POAction,
  auth: GWAuth,
  notes?: string,
): Promise<void> {
  const cur = await client.query(`SELECT status FROM purchase_orders WHERE id=$1 FOR UPDATE`, [
    poId,
  ])
  if (!cur.rows[0])
    throw Object.assign(new Error('PO not found'), { extensions: { code: 'NOT_FOUND' } })
  const cs = cur.rows[0].status as POStatus
  if (cs !== fromStatus)
    throw Object.assign(new Error(`Expected '${fromStatus}', got '${cs}'`), {
      extensions: { code: 'INVALID_STATUS' },
    })
  if (!poStateMachine.canTransition(cs, action))
    throw Object.assign(new Error(`Action '${action}' not allowed from '${cs}'`), {
      extensions: { code: 'INVALID_TRANSITION' },
    })
  await client.query(`UPDATE purchase_orders SET status=$1, updated_at=NOW() WHERE id=$2`, [
    toStatus,
    poId,
  ])
  await client.query(
    `INSERT INTO po_approval_log (po_id, from_status, to_status, action, actor_id, notes) VALUES ($1,$2,$3,$4,$5,$6)`,
    [poId, fromStatus, toStatus, action, auth.userId, notes ?? null],
  )
  await logAudit({
    userId: auth.userId,
    companyId: auth.companyId,
    action,
    tableName: 'purchase_orders',
    recordId: poId,
    oldValues: { status: fromStatus },
    newValues: { status: toStatus },
    client,
  })
}

async function getPOForReturn(poId: string): Promise<Record<string, unknown>> {
  const r = await query(
    `SELECT po.*, v.name AS vendor_name,
            fadv.advance_number AS funding_advance_number, fadv.employee_name AS funding_employee_name
     FROM purchase_orders po
     LEFT JOIN vendors v ON v.id=po.vendor_id
     LEFT JOIN employee_advances fadv ON fadv.id=po.funding_advance_id
     WHERE po.id=$1`,
    [poId],
  )
  if (!r.rows[0]) throw new Error('PO not found')
  return r.rows[0] as Record<string, unknown>
}

// True if the caller holds an active 'po_admin' position assignment in this
// company. Company-wide by nature (managing PO positions isn't scoped to a
// specific project/department), so no project/department matching needed.
async function callerHasPOAdmin(userId: string, companyId: string): Promise<boolean> {
  const r = await query(
    `SELECT 1 FROM po_position_assignments ppa
     JOIN employees e ON e.id = ppa.employee_id
     WHERE e.user_id = $1 AND ppa.company_id = $2 AND ppa.position = 'po_admin' AND ppa.is_active = true
     LIMIT 1`,
    [userId, companyId],
  )
  return r.rows.length > 0
}

// True if the caller holds an active company-wide 'store_keeper' position
// assignment (project_id IS NULL AND department_id IS NULL). Stock
// adjustments aren't tied to a PO/project/department — stock_locations has
// no department_id/project_id column — so unlike userHasPositionGW (which
// resolves scope from a PO), this only recognizes a company-wide grant.
async function callerHasCompanyWideStoreKeeper(
  userId: string,
  companyId: string,
): Promise<boolean> {
  const r = await query(
    `SELECT 1 FROM po_position_assignments ppa
     JOIN employees e ON e.id = ppa.employee_id
     WHERE e.user_id = $1 AND ppa.company_id = $2 AND ppa.position = 'store_keeper'
       AND ppa.is_active = true AND ppa.project_id IS NULL AND ppa.department_id IS NULL
       AND ppa.branch_id IS NULL
     LIMIT 1`,
    [userId, companyId],
  )
  return r.rows.length > 0
}

// Post a journal entry when a project-linked PO is completed so that the cost
// flows into project_cost_actuals via trg_sync_project_costs.
async function postPOCompletionJournal(
  client: import('@fnc-erp/db').PoolClient,
  poId: string,
  actorId: string,
): Promise<void> {
  const poRes = await client.query(
    `SELECT po.id, po.po_number, po.project_id, po.total_amount, po.currency_code,
            po.fx_rate, po.funding_source, p.analytic_account_id, p.company_id AS project_company_id
     FROM purchase_orders po
     LEFT JOIN projects p ON p.id = po.project_id
     WHERE po.id = $1`,
    [poId],
  )
  const po = poRes.rows[0] as Record<string, unknown> | undefined
  if (!po?.project_id || !po.analytic_account_id) return // not a project PO or no analytic account
  // Employee-advance-funded POs settle through advance settlements
  // (services/finance/src/routes/employee-advances.ts), not a vendor AP
  // entry — posting one here would be a phantom payable no one will ever pay.
  if (po.funding_source === 'employee_advance') return
  const totalAmount = parseFloat(String(po.total_amount ?? 0))
  if (totalAmount <= 0) return

  const companyId = String(po.project_company_id)
  const currencyCode = String(po.currency_code ?? 'IQD')
  let fxRate = 1.0
  if (currencyCode !== 'IQD') {
    const fxRes = await client.query(
      `SELECT rate FROM fx_rates
       WHERE from_currency = $1 AND to_currency = 'IQD'
       ORDER BY rate_date DESC LIMIT 1`,
      [currencyCode],
    )
    fxRate = fxRes.rows[0] ? parseFloat(String(fxRes.rows[0].rate)) : 1.0
  }
  const amountCompanyCurrency = totalAmount * fxRate
  const poNumber = String(po.po_number)
  const analyticAccountId = String(po.analytic_account_id)

  const expAcctRes = await client.query(
    `SELECT id FROM chart_of_accounts WHERE company_id=$1 AND account_type='expense' AND is_active=true ORDER BY code ASC LIMIT 1`,
    [companyId],
  )
  const apAcctRes = await client.query(
    `SELECT id FROM chart_of_accounts WHERE company_id=$1 AND account_type='liability' AND is_active=true ORDER BY code ASC LIMIT 1`,
    [companyId],
  )
  const expAccountId = expAcctRes.rows[0]?.id as string | undefined
  const apAccountId = apAcctRes.rows[0]?.id as string | undefined
  if (!expAccountId || !apAccountId) return // no GL accounts configured, skip silently

  const je = await client.query(
    `INSERT INTO journal_entries (company_id,reference,description,entry_date,status,source_type,source_id,created_by,posted_at,posted_by)
     VALUES ($1,$2,$3,CURRENT_DATE,'posted','po_completion',$4,$5,NOW(),$5) RETURNING id`,
    [companyId, `PO-${poNumber}-COST`, `Project cost from PO ${poNumber}`, poId, actorId],
  )
  const jeId = je.rows[0].id as string

  // Link this journal to the source PO
  await client.query(
    `INSERT INTO journal_po_links (journal_entry_id, po_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`,
    [jeId, poId],
  )

  // Dr. Project Expense (tagged with analytic account → triggers trg_sync_project_costs)
  await client.query(
    `INSERT INTO journal_lines (journal_entry_id,account_id,analytic_account_id,description,debit,credit,currency_code,fx_rate,amount_company_currency)
     VALUES ($1,$2,$3,$4,$5,0,$6,$7,$8)`,
    [
      jeId,
      expAccountId,
      analyticAccountId,
      `Project expense from PO ${poNumber}`,
      totalAmount,
      currencyCode,
      fxRate,
      amountCompanyCurrency,
    ],
  )
  // Cr. Accounts Payable
  await client.query(
    `INSERT INTO journal_lines (journal_entry_id,account_id,description,debit,credit,currency_code,fx_rate,amount_company_currency)
     VALUES ($1,$2,$3,0,$4,$5,$6,$7)`,
    [
      jeId,
      apAccountId,
      `Payable for PO ${poNumber}`,
      totalAmount,
      currencyCode,
      fxRate,
      amountCompanyCurrency,
    ],
  )
}

// Auto-creates a draft Store Out for every po_lines row with qty_from_stock > 0
// on a PO — no stock actually moves here anymore. Used both by the
// 100%-stock-covered fast path (approveStockIssuance, ready_to_issue →
// completed) and by the normal approval path for mixed POs (approvePO) — a PO
// with no from-stock lines is a safe no-op either way. Each line records
// where it would come from (po_lines.source_location_id, falling back to the
// company's own warehouse) and its cost, but the actual stock_moves (and, for
// a cross-company source location, the interco transfer) only happen when a
// human confirms the Store Out — see issueMaterialIssue.
// The warehouse/"Project Consumption" location pair used for every stock
// issuance line, whether issued at the time the PO's stock issuance is
// approved or retroactively once a pending catalog item gets resolved.
async function getStockIssuanceLocations(
  client: PoolClient,
  companyId: string,
): Promise<{ defaultFromLocationId: string; ownDestLocationId: string }> {
  const warehouseRes = await client.query(
    `SELECT id FROM stock_locations WHERE company_id=$1 AND type='warehouse' AND is_active=true LIMIT 1`,
    [companyId],
  )
  const fallbackRes = await client.query(
    `SELECT id FROM stock_locations WHERE company_id=$1 AND is_active=true LIMIT 1`,
    [companyId],
  )
  const defaultFromLocationId = (warehouseRes.rows[0]?.id ?? fallbackRes.rows[0]?.id) as
    | string
    | undefined
  if (!defaultFromLocationId) throw new Error('No warehouse location found for company')

  const destRes = await client.query(
    `SELECT id FROM stock_locations WHERE company_id=$1 AND type='virtual_out' AND is_active=true LIMIT 1`,
    [companyId],
  )
  // Falling back to defaultFromLocationId here would move stock from the
  // warehouse right back to itself (a net no-op) once confirming actually
  // moves it — auto-create the "consumed by project" placeholder instead,
  // mirroring how virtual_in/virtual_out already get auto-created below.
  const ownDestLocationId: string = (destRes.rows[0]?.id ??
    (
      await client.query(
        `INSERT INTO stock_locations (company_id, name, type, is_active) VALUES ($1,'Project Consumption','virtual_out',true) RETURNING id`,
        [companyId],
      )
    ).rows[0].id) as string

  return { defaultFromLocationId, ownDestLocationId }
}

// Inserts one project_material_issue_lines row for a po_line that's now
// known to have a real product_id. Shared by the main per-PO loop below and
// by the retroactive completion that runs when a stock_issuance-sourced
// pending catalog item gets resolved after the fact.
async function insertStockIssuanceLine(
  client: PoolClient,
  issueId: string,
  line: Record<string, unknown>,
  defaultFromLocationId: string,
  ownDestLocationId: string,
): Promise<void> {
  const qty = parseFloat(String(line.qty_from_stock ?? 0))
  const fromLocationId = (line.source_location_id as string | null) ?? defaultFromLocationId

  // Use store_price if set on the line; fall back to average_cost from stock
  const costRes = await client.query(
    `SELECT COALESCE(
       NULLIF(pol.store_price, 0),
       (SELECT sb.average_cost FROM stock_balances sb
        WHERE sb.product_id=pol.product_id AND sb.location_id=$2 LIMIT 1),
       0
     ) AS unit_cost
     FROM po_lines pol WHERE pol.id=$1`,
    [line.id, fromLocationId],
  )
  const unitCost = parseFloat(String(costRes.rows[0]?.unit_cost ?? 0))
  const lineCost = qty * unitCost

  await client.query(
    `INSERT INTO project_material_issue_lines
       (issue_id, product_id, po_line_id, qty_issued, unit_cost, total_cost,
        from_location_id, to_location_id)
     VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
    [issueId, line.product_id, line.id, qty, unitCost, lineCost, fromLocationId, ownDestLocationId],
  )
}

// Once a stock_issuance-sourced pending catalog item is resolved (its
// po_line now has a real product_id), completes the Store Out that was
// auto-created back when the PO's stock issuance was approved — that draft
// still exists with zero lines for this item, since resolving only fixed
// the product identity going forward, not the historical transaction. A
// no-op if there's no such draft (e.g. the PO never went through this path)
// or a line for it already exists (resolve can't normally run twice, since
// it requires status='pending', but this keeps it safe either way).
async function completeStockIssuanceLineForResolvedProduct(
  client: PoolClient,
  poLineId: string,
  companyId: string,
): Promise<void> {
  const lineRes = await client.query(`SELECT * FROM po_lines WHERE id=$1`, [poLineId])
  const line = lineRes.rows[0] as Record<string, unknown> | undefined
  if (!line || !line.product_id) return

  const issueRes = await client.query(
    `SELECT pmi.id FROM project_material_issues pmi
     JOIN po_lines pl ON pl.po_id = pmi.po_id
     WHERE pl.id = $1
     LIMIT 1`,
    [poLineId],
  )
  const issueId = issueRes.rows[0]?.id as string | undefined
  if (!issueId) return

  const existingLine = await client.query(
    `SELECT 1 FROM project_material_issue_lines WHERE po_line_id=$1`,
    [poLineId],
  )
  if (existingLine.rows[0]) return

  const { defaultFromLocationId, ownDestLocationId } = await getStockIssuanceLocations(
    client,
    companyId,
  )
  await insertStockIssuanceLine(client, issueId, line, defaultFromLocationId, ownDestLocationId)
}

async function issueStockForPOLines(
  client: PoolClient,
  po: Record<string, unknown>,
  companyId: string,
  userId: string,
): Promise<{ issueId: string; issueNumber: string } | undefined> {
  // A project PO explicitly marked "delivered to inventory" isn't consuming
  // anything yet — its from-stock quantity should just stay put (no auto
  // Store Out), the same way its freshly-purchased lines skip Store In under
  // recordDirectDelivery's counterpart. Only 'jobsite' (or a non-project PO,
  // where this destination concept doesn't apply) still issues stock out to
  // the project.
  if (po.purpose === 'project' && po.delivery_destination === 'inventory') return undefined

  const poId = String(po.id)
  const linesRes = await client.query(
    `SELECT * FROM po_lines WHERE po_id=$1 AND qty_from_stock > 0`,
    [poId],
  )
  const lines = linesRes.rows as Record<string, unknown>[]
  if (lines.length === 0) return undefined

  const { defaultFromLocationId, ownDestLocationId } = await getStockIssuanceLocations(
    client,
    companyId,
  )

  // Draft Store Out — the store keeper must explicitly confirm it
  // (issueMaterialIssue) before stock actually leaves inventory, exactly
  // like a manually-created one.
  const issueNumber = await nextDocumentNumber(companyId, 'material_issue', 'SO')

  const issueRes = await client.query(
    `INSERT INTO project_material_issues
       (project_id, company_id, po_id, issue_number, issue_date, status,
        created_by, notes)
     VALUES ($1,$2,$3,$4,NOW()::date,'draft',$5,
             'Auto-created from PO stock issuance')
     RETURNING id`,
    [po.project_id, companyId, poId, issueNumber, userId],
  )
  const issueId = issueRes.rows[0]?.id as string

  for (const line of lines) {
    const qty = parseFloat(String(line.qty_from_stock ?? 0))
    if (qty <= 0) continue
    if (!line.product_id) {
      // A store keeper can mark any line as covered from stock during
      // inventory check, including one for a free-text item never matched
      // to a catalog product — there's no product identity to book a stock
      // move or a material-issue line against, so it used to just vanish
      // here silently (the store keeper believed it was issued; nothing
      // was ever recorded). Queue it on the same worklist store_in/
      // direct_delivery already use for this exact situation, instead of
      // dropping it. See completeStockIssuanceLineForResolvedProduct for
      // what happens once it's resolved.
      await client.query(
        `INSERT INTO pending_product_catalog_items
           (company_id, po_id, po_line_id, description, qty, uom, unit_price, currency_code, source)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'stock_issuance')
         ON CONFLICT (po_line_id) DO NOTHING`,
        [
          companyId,
          poId,
          line.id,
          line.description ?? '',
          qty,
          line.uom ?? 'unit',
          line.unit_price ?? null,
          line.currency_code ?? null,
        ],
      )
      continue
    }
    await insertStockIssuanceLine(client, issueId, line, defaultFromLocationId, ownDestLocationId)
  }
  // Cost booking (project_cost_actuals) and issued_by/issued_at stamping are
  // deferred to issueMaterialIssue, which runs once the store keeper confirms
  // this draft — see that resolver for the actual upsert.
  return { issueId, issueNumber }
}

// Returns to inventory whatever issueStockForPOLines previously deducted for this
// PO, by inserting the mirror-image stock_moves row for each move it made (same
// product/qty/cost, from/to swapped) — a no-op if nothing was ever deducted (e.g.
// the PO was cancelled before reaching the point stock actually moves). Restores
// only the physical stock; it deliberately does not unwind the Store Out record
// or its project cost-actuals entry, which stay as a historical record of what
// happened.
async function reverseStockIssuanceForPO(
  client: PoolClient,
  poId: string,
  userId: string,
): Promise<void> {
  const movesRes = await client.query(
    `SELECT * FROM stock_moves WHERE source_type='po_stock_issuance' AND source_id=$1 ORDER BY moved_at`,
    [poId],
  )
  for (const move of movesRes.rows as Record<string, unknown>[]) {
    await client.query(
      `INSERT INTO stock_moves (company_id,product_id,from_location_id,to_location_id,moved_at,qty,unit_cost,total_cost,source_type,source_id,notes,moved_by)
       VALUES ($1,$2,$3,$4,NOW(),$5,$6,$7,'po_stock_issuance',$8,$9,$10)`,
      [
        move.company_id,
        move.product_id,
        move.to_location_id,
        move.from_location_id,
        move.qty,
        move.unit_cost,
        move.total_cost,
        poId,
        'Reversal — PO cancelled',
        userId,
      ],
    )
  }
}

// ── Manufacturing Request helpers ────────────────────────────────
function mapMR(row: Record<string, unknown>) {
  return {
    id: row.id,
    requestNumber: row.request_number,
    projectId: row.project_id,
    projectName: row.project_name ?? null,
    requestingCompanyId: row.requesting_company_id,
    requestingCompanyName: row.requesting_company_name ?? null,
    productId: row.product_id ?? null,
    productName: row.product_name ?? null,
    productSku: row.product_sku ?? null,
    qtyRequested: parseFloat(String(row.qty_requested ?? 1)),
    requiredDate: row.required_date ? String(row.required_date) : null,
    description: row.description ?? null,
    status: row.status,
    requestedBy: row.requested_by,
    requestedByName: row.requested_by_name ?? null,
    approvedBy: row.approved_by ?? null,
    approvedByName: row.approved_by_name ?? null,
    approvedAt: row.approved_at ? String(row.approved_at) : null,
    rejectionReason: row.rejection_reason ?? null,
    moId: row.mo_id ?? null,
    moNumber: row.mo_number ?? null,
    actualCost: row.actual_cost ? parseFloat(String(row.actual_cost)) : null,
    currencyCode: String(row.currency_code ?? 'IQD').trim(),
    notes: row.notes ?? null,
    createdAt: String(row.created_at),
  }
}

const MR_SELECT = `
  SELECT mr.*,
    p.name   AS project_name,
    c.name   AS requesting_company_name,
    prod.name AS product_name,
    prod.sku  AS product_sku,
    COALESCE(ru.first_name || ' ' || ru.last_name, ru.email) AS requested_by_name,
    COALESCE(au.first_name || ' ' || au.last_name, au.email) AS approved_by_name,
    mo.mo_number
  FROM manufacturing_requests mr
  LEFT JOIN projects p ON p.id = mr.project_id
  LEFT JOIN companies c ON c.id = mr.requesting_company_id
  LEFT JOIN products prod ON prod.id = mr.product_id
  LEFT JOIN users ru ON ru.id = mr.requested_by
  LEFT JOIN users au ON au.id = mr.approved_by
  LEFT JOIN manufacturing_orders mo ON mo.id = mr.mo_id
`

async function getEmployeeIdGW(userId: string, companyId: string): Promise<string | null> {
  const r = await query(`SELECT id FROM employees WHERE user_id=$1 AND company_id=$2 LIMIT 1`, [
    userId,
    companyId,
  ])
  return (r.rows[0]?.id as string | null) ?? null
}

async function userHasPositionGW(
  userId: string,
  companyId: string,
  poId: string,
  position: string,
): Promise<boolean> {
  const scope = await query(
    `SELECT po.project_id, po.branch_id, e.department_id FROM purchase_orders po LEFT JOIN users ou ON ou.id=po.organizer_id LEFT JOIN employees e ON e.user_id=ou.id WHERE po.id=$1 LIMIT 1`,
    [poId],
  )
  if (!scope.rows[0]) return false
  const empId = await getEmployeeIdGW(userId, companyId)
  if (!empId) return false
  // Company-wide fallback requires ALL scope dimensions to be null on the
  // assignment row — otherwise a branch-only (or project/department-only)
  // assignment would incorrectly match every PO regardless of scope.
  const r = await query(
    `SELECT id FROM po_position_assignments WHERE employee_id=$1 AND position=$2 AND is_active=true AND company_id=$3 AND (($4::uuid IS NOT NULL AND project_id=$4) OR ($5::uuid IS NOT NULL AND department_id=$5) OR ($6::uuid IS NOT NULL AND branch_id=$6) OR (project_id IS NULL AND department_id IS NULL AND branch_id IS NULL)) LIMIT 1`,
    [
      empId,
      position,
      companyId,
      scope.rows[0].project_id ?? null,
      scope.rows[0].department_id ?? null,
      scope.rows[0].branch_id ?? null,
    ],
  )
  return r.rows.length > 0
}

async function userIsOrganizerGW(
  userId: string,
  poId: string,
  companyId: string,
): Promise<boolean> {
  const r = await query(
    `SELECT id FROM purchase_orders WHERE id=$1 AND organizer_id=$2 AND company_id=$3 LIMIT 1`,
    [poId, userId, companyId],
  )
  return r.rows.length > 0
}

// Same definition already used by notifyFinanceTeamGW's recipient list — kept
// as a single-user check here for the view-gate rather than duplicating the
// SQL a third time.
async function isUserFinanceTeamGW(userId: string, companyId: string): Promise<boolean> {
  const r = await query(
    `SELECT 1 FROM user_company_roles
     WHERE user_id=$1 AND company_id=$2 AND is_active=true
       AND (role IN ('company_admin', 'system_admin')
            OR (module = 'finance' AND role IN ('module_admin', 'module_user')))
     LIMIT 1`,
    [userId, companyId],
  )
  return r.rows.length > 0
}

// Whether the caller holds whatever authority actually gates *acting* on the
// PO's current stage — mirrors each stage's own mutation-level check exactly
// (submitPOStorePricing, submitPOMarketPricing, submitPOPriceVerification,
// approvePO, approveStockIssuance, markPOLineBought) so PO-detail visibility
// and the ability to act on it never disagree. Stages with no dedicated
// position (draft, inventory_check, approved, goods_received, and terminal
// states) fall through to false — those are organizer/admin-only, handled by
// the caller alongside this check.
async function callerHasCurrentStagePositionGW(
  auth: GWAuth,
  poId: string,
  status: string,
): Promise<boolean> {
  switch (status) {
    case 'store_pricing':
      return userHasPositionGW(auth.userId, auth.companyId, poId, 'store_pricing')
    case 'market_pricing':
      return userHasPositionGW(auth.userId, auth.companyId, poId, 'procurement_officer')
    case 'price_verification':
      return userHasPositionGW(auth.userId, auth.companyId, poId, 'procurement_2nd')
    case 'pending_approval':
      return (
        (await userIsDeptHeadGW(auth.userId, poId)) ||
        (await userIsAssignedApproverGW(auth.userId, poId)) ||
        (await callerHasPOAdmin(auth.userId, auth.companyId))
      )
    case 'ready_to_issue':
      return userHasPositionGW(auth.userId, auth.companyId, poId, 'store_keeper')
    case 'items_bought':
      return userHasPositionGW(auth.userId, auth.companyId, poId, 'buyer')
    default:
      return false
  }
}

// The full purchase-order shape (header + lines + receipts + approval log +
// edit requests + caller-position flags) — extracted so purchaseOrder(id)
// and purchaseOrderForAction(id) share one implementation instead of two
// copies of this SQL drifting apart. Returns null if the PO doesn't exist,
// isn't in this company, or is outside the caller's branch scope. Neither
// caller adds viewerRestricted; each sets it appropriately for its own case.
async function fetchFullPurchaseOrderGW(
  id: string,
  auth: GWAuth,
): Promise<Record<string, unknown> | null> {
  const [po, lines, receipts, approvals] = await Promise.all([
    query(
      `SELECT po.*, v.name AS vendor_name, COALESCE(u.first_name || ' ' || u.last_name, u.email) AS created_by_email,
              aa.name AS analytic_account_name, COALESCE(au.first_name || ' ' || au.last_name, au.email) AS assigned_to_email,
              po.linked_project_id AS "linkedProjectId", po.linked_mo_id AS "linkedMoId",
              proj.code AS "projectCode", proj.name AS "projectName",
              cb.name AS branch_name,
              COALESCE(NULLIF(TRIM(re.first_name || ' ' || re.last_name), ''), re.email) AS assigned_receiver_name,
              fadv.advance_number AS funding_advance_number, fadv.employee_name AS funding_employee_name,
              COALESCE(NULLIF(TRIM(bu.first_name || ' ' || bu.last_name), ''), bu.email) AS assigned_buyer_name
       FROM purchase_orders po
       LEFT JOIN vendors v ON v.id=po.vendor_id
       LEFT JOIN users u ON u.id=po.created_by
       LEFT JOIN analytic_accounts aa ON aa.id=po.analytic_account_id
       LEFT JOIN users au ON au.id=po.assigned_to
       LEFT JOIN employees re ON re.id=po.assigned_receiver_id
       LEFT JOIN projects proj ON proj.id=po.project_id
       LEFT JOIN company_branches cb ON cb.id=po.branch_id
       LEFT JOIN employee_advances fadv ON fadv.id=po.funding_advance_id
       LEFT JOIN users bu ON bu.id=po.assigned_buyer_user_id
       WHERE po.id=$1 AND po.company_id=$2`,
      [id, auth.companyId],
    ),
    query(
      `SELECT pol.id, pol.po_id, pol.description, pol.product_id, pol.qty_ordered AS qty,
              pol.qty_received, pol.unit_price, pol.initial_unit_price, pol.total_price AS total, pol.currency_code, pol.uom,
              pol.requested_currency_code, pol.fx_rate_to_base,
              pol.actual_unit_price,
              pol.store_price, pol.store_price_currency,
              pol.market_price, pol.market_price_currency, pol.verified_price, pol.verified_price_currency,
              pol.in_stock, pol.qty_from_stock,
              pol.source_location_id, sl.name AS source_location_name,
              sl.company_id AS source_company_id, sc.name AS source_company_name,
              sb.average_cost AS source_average_cost,
              pol.audit_status, pol.audit_note, pol.audit_flagged_by_email, pol.audit_flagged_at,
              pol.line_number, p.name AS product_name, p.name_ar AS product_name_ar, p.sku,
              pol.account_id, coa.code AS account_code, coa.name AS account_name,
              pol.cost_center_id, cc.name AS cost_center_name, pol.advance_settlement_id,
              pol.is_bought
       FROM po_lines pol
       LEFT JOIN products p ON p.id=pol.product_id
       LEFT JOIN stock_locations sl ON sl.id=pol.source_location_id
       LEFT JOIN companies sc ON sc.id=sl.company_id
       LEFT JOIN stock_balances sb ON sb.product_id=pol.product_id AND sb.location_id=pol.source_location_id AND sb.lot_id IS NULL
       LEFT JOIN chart_of_accounts coa ON coa.id=pol.account_id
       LEFT JOIN cost_centers cc ON cc.id=pol.cost_center_id
       WHERE pol.po_id=$1 ORDER BY pol.line_number`,
      [id],
    ),
    query(
      `SELECT por.id, por.po_id, por.receipt_number, por.received_date AS receipt_date,
              por.received_by, por.received_by_name, por.received_from_name, por.location_notes, por.notes, por.created_at, por.is_invoiced, por.status, por.confirmed_at,
              sl.name AS location_name, COALESCE(u.first_name || ' ' || u.last_name, u.email) AS received_by_email,
              COALESCE(json_agg(DISTINCT jsonb_build_object('po_line_id',porl.po_line_id,'qty_received',porl.qty_received,'description',COALESCE(pol.description, ''),'product_name',p.name,'sku',p.sku,'uom',pol.uom,'unit_price',pol.unit_price,'currency_code',pol.currency_code,'fx_rate_to_base',pol.fx_rate_to_base)) FILTER (WHERE porl.id IS NOT NULL), '[]') AS lines,
              COALESCE(json_agg(DISTINCT jsonb_build_object('id',da.id,'fileId',f.id,'label',da.label,'category',f.category,'originalFilename',f.original_filename,'fileKey',f.file_key,'createdAt',da.created_at)) FILTER (WHERE da.id IS NOT NULL AND f.id IS NOT NULL), '[]') AS photos
       FROM po_receipts por
       LEFT JOIN stock_locations sl ON sl.id=por.warehouse_location_id
       LEFT JOIN users u ON u.id=por.received_by
       LEFT JOIN po_receipt_lines porl ON porl.receipt_id=por.id
       LEFT JOIN po_lines pol ON pol.id=porl.po_line_id
       LEFT JOIN products p ON p.id=pol.product_id
       LEFT JOIN document_attachments da ON da.entity_type='po_receipt' AND da.entity_id=por.id
       LEFT JOIN files f ON f.id=da.file_id AND f.status != 'deleted'
       WHERE por.po_id=$1
       GROUP BY por.id, sl.name, u.email, u.first_name, u.last_name ORDER BY por.received_date`,
      [id],
    ),
    query(
      `SELECT poa.id, poa.po_id, poa.from_status, poa.to_status, poa.action, poa.notes, poa.created_at,
              COALESCE(u.first_name || ' ' || u.last_name, u.email) AS user_email
       FROM po_approval_log poa LEFT JOIN users u ON u.id=poa.actor_id
       WHERE poa.po_id=$1 ORDER BY poa.created_at`,
      [id],
    ),
  ])
  if (!po.rows[0]) return null
  const branchScope = await branchScopedPOFilterGW(auth)
  if (branchScope && !branchScope.includes((po.rows[0] as Record<string, unknown>).branch_id as string)) {
    return null
  }
  const poRowForBuyer = po.rows[0] as Record<string, unknown>
  // Buyer authority is now resolved dynamically from the 'buyer'
  // position rather than a single frozen assignee — compute the
  // current holder(s) for display, falling back to the legacy
  // assigned_buyer_name for pre-cutover POs with no matching position.
  const buyerHolders = await query<{ name: string }>(
    `SELECT DISTINCT COALESCE(NULLIF(TRIM(u.first_name || ' ' || u.last_name), ''), u.email) AS name
     FROM po_position_assignments ppa
     JOIN employees e ON e.id = ppa.employee_id
     JOIN users u ON u.id = e.user_id
     WHERE ppa.position = 'buyer' AND ppa.is_active = true AND ppa.company_id = $1
       AND (($2::uuid IS NOT NULL AND ppa.branch_id = $2)
         OR (ppa.project_id IS NULL AND ppa.department_id IS NULL AND ppa.branch_id IS NULL))`,
    [auth.companyId, poRowForBuyer.branch_id ?? null],
  )
  const buyerNames = buyerHolders.rows.map((r) => r.name)
  const isAdminForBuyer = isAdminGW(auth.role)
  const isFrozenBuyerForCaller = poRowForBuyer.assigned_buyer_user_id === auth.userId
  const callerIsBuyer =
    isAdminForBuyer ||
    isFrozenBuyerForCaller ||
    (await userHasPositionGW(auth.userId, auth.companyId, id, 'buyer'))
  // Mirrors submitPOStorePricing/submitPOMarketPricing's own authorization
  // exactly (no organizer fallback — see those resolvers' comments), so the
  // store/market pricing forms can be hidden client-side for someone who'd
  // just get rejected on submit anyway, instead of letting them type values
  // into a form they can't actually save.
  const callerHasStorePricingPosition =
    isAdminForBuyer || (await userHasPositionGW(auth.userId, auth.companyId, id, 'store_pricing'))
  const callerHasMarketPricingPosition =
    isAdminForBuyer ||
    (await userHasPositionGW(auth.userId, auth.companyId, id, 'procurement_officer'))
  let editRequests: unknown[] = []
  try {
    const er = await query(
      `SELECT er.*, req.email AS requested_by_email, rev.email AS reviewed_by_email
       FROM po_edit_requests er
       JOIN users req ON req.id = er.requested_by
       LEFT JOIN users rev ON rev.id = er.reviewed_by
       WHERE er.po_id = $1 ORDER BY er.created_at DESC`,
      [id],
    )
    editRequests = er.rows.map((r) => ({ ...r, changes: JSON.stringify(r.changes) }))
  } catch {
    /* ignore if table absent */
  }
  const receiptsWithUrls = await Promise.all(
    receipts.rows.map(async (r) => {
      const row = r as Record<string, unknown>
      const photos = (row.photos as Record<string, unknown>[]) ?? []
      const photosWithUrls = await Promise.all(
        photos.map(async (ph) => {
          const fileKey = ph.fileKey as string | undefined
          if (!fileKey) return { ...ph, downloadUrl: null }
          try {
            const { downloadUrl } = await generateDownloadUrl(fileKey, ph.originalFilename as string)
            return { ...ph, downloadUrl }
          } catch {
            return { ...ph, downloadUrl: null }
          }
        }),
      )
      return { ...row, photos: photosWithUrls }
    }),
  )
  return {
    ...po.rows[0],
    lines: lines.rows,
    receipts: receiptsWithUrls,
    approval_log: approvals.rows,
    edit_requests: editRequests,
    buyerNames,
    callerIsBuyer,
    callerHasStorePricingPosition,
    callerHasMarketPricingPosition,
  }
}

// document_attachments is polymorphic (entity_type + entity_id, no FK) —
// the generic attachFile/detachFile/entityAttachments resolvers never
// verified the target entity actually belongs to the caller's company,
// only that the *file* did. Every entity-specific upload mutation (RFI,
// NCR, site instruction, etc.) already guards this itself via its own
// JOIN; this covers the entity types actually reachable through the
// generic path from the live frontend (employee documents, Store Out
// signed copies). Extend this switch if a new entity type starts using
// attachFile/detachFile/entityAttachments directly.
async function verifyAttachmentEntityOwnershipGW(
  entityType: string,
  entityId: string,
  companyId: string,
): Promise<boolean> {
  switch (entityType) {
    case 'employee': {
      const r = await query(`SELECT id FROM employees WHERE id=$1 AND company_id=$2`, [
        entityId,
        companyId,
      ])
      return r.rows.length > 0
    }
    case 'material_issue': {
      const r = await query(
        `SELECT id FROM project_material_issues WHERE id=$1 AND company_id=$2`,
        [entityId, companyId],
      )
      return r.rows.length > 0
    }
    case 'po_receipt': {
      const r = await query(
        `SELECT por.id FROM po_receipts por JOIN purchase_orders po ON po.id=por.po_id
         WHERE por.id=$1 AND po.company_id=$2`,
        [entityId, companyId],
      )
      return r.rows.length > 0
    }
    case 'purchase_order': {
      const r = await query(`SELECT id FROM purchase_orders WHERE id=$1 AND company_id=$2`, [
        entityId,
        companyId,
      ])
      return r.rows.length > 0
    }
    default:
      return true
  }
}

async function deriveRfqNumber(companyId: string, projectCode: string): Promise<string> {
  const [projSeq, rfqSeq] = await Promise.all([
    query(
      `SELECT prefix, separator FROM document_sequences WHERE company_id=$1 AND doc_type='project' LIMIT 1`,
      [companyId],
    ),
    query(
      `SELECT prefix, separator FROM document_sequences WHERE company_id=$1 AND doc_type='rfq'     LIMIT 1`,
      [companyId],
    ),
  ])
  const projPrefix = String((projSeq.rows[0] as Record<string, unknown>).prefix ?? 'PRJ')
  const projSep = String((projSeq.rows[0] as Record<string, unknown>).separator ?? '-')
  const rfqPrefix = String((rfqSeq.rows[0] as Record<string, unknown>).prefix ?? 'RFQ')
  const rfqSep = String((rfqSeq.rows[0] as Record<string, unknown>).separator ?? '-')
  const suffix = projectCode.slice(projPrefix.length + projSep.length) // e.g. '2026-0005'
  return `${rfqPrefix}${rfqSep}${suffix}`
}

async function userIsDeptHeadGW(userId: string, poId: string): Promise<boolean> {
  const r = await query(
    `SELECT 1 FROM departments d JOIN employees mgr ON mgr.id=d.manager_id JOIN users mu ON mu.id=mgr.user_id
     WHERE mu.id=$1 AND d.id=(SELECT e.department_id FROM employees e JOIN users ou ON ou.id=e.user_id JOIN purchase_orders po ON po.organizer_id=ou.id WHERE po.id=$2 LIMIT 1) LIMIT 1`,
    [userId, poId],
  )
  return r.rows.length > 0
}

async function userIsAssignedApproverGW(userId: string, poId: string): Promise<boolean> {
  const r = await query(
    `SELECT 1 FROM purchase_orders po JOIN employees e ON e.id=po.assigned_approver_id JOIN users u ON u.id=e.user_id WHERE po.id=$1 AND u.id=$2 LIMIT 1`,
    [poId, userId],
  )
  return r.rows.length > 0
}

function isAdminGW(role: string): boolean {
  return ['system_admin', 'company_admin', 'module_admin'].includes(role)
}

// Only system_admin/company_admin auto-bypass granular permission checks —
// module_admin needs permissions explicitly granted like anyone else. This
// is the same rule packages/permissions/src/middleware.ts's requirePermission
// enforces everywhere else; isAdminGW (which also includes module_admin) is
// for a different purpose (organizer/PO-authority checks) and must not be
// used here.
function isPermissionBypassGW(role: string): boolean {
  return role === 'system_admin' || role === 'company_admin'
}

// Gates the finance_audit/invoiced stages. System-wide finance capability,
// not PO-specific — 'finance' was never part of the real role vocabulary
// (user/module_admin/company_admin/system_admin), so this was previously
// unreachable by anyone but admins. Mirrors hasFinanceApproval in
// services/procurement/src/routes/orders.ts.
async function hasFinanceApprovalGW(
  userId: string,
  companyId: string,
  role: string,
): Promise<boolean> {
  if (isPermissionBypassGW(role)) return true
  const perms = await loadPermissions(userId, companyId)
  return meetsLevel(perms['finance.ap.approve'], 'approve')
}

// Generic granular-permission check for GraphQL mutations, matching
// requirePermission's semantics exactly (system_admin/company_admin bypass,
// everyone else needs the key granted at minLevel). Throws on failure.
async function requirePermGW(
  auth: { userId: string; companyId: string; role: string },
  permKey: string,
  minLevel: 'view' | 'edit' | 'approve' | 'admin',
): Promise<void> {
  if (isPermissionBypassGW(auth.role)) return
  const perms = await loadPermissions(auth.userId, auth.companyId)
  if (!meetsLevel(perms[permKey], minLevel)) {
    throw new Error(`Requires '${minLevel}' access to '${permKey}'`)
  }
}

// A user is a "branch-only procurement buyer" when they're set as one or
// more branches' default_procurement_user_id and don't otherwise hold
// edit-level PO access — that combination means their PO visibility should
// be limited to just those branches instead of the company-wide default
// every other viewer gets. Returns the branch ids to scope to, or null if
// no scoping applies (this user sees POs exactly as they always have —
// true for everyone until an admin explicitly assigns them to a branch).
async function branchScopedPOFilterGW(
  auth: { userId: string; companyId: string; role: string },
): Promise<string[] | null> {
  if (isPermissionBypassGW(auth.role)) return null
  const perms = await loadPermissions(auth.userId, auth.companyId)
  if (meetsLevel(perms['procurement.po.edit'], 'edit')) return null
  const empId = await getEmployeeIdGW(auth.userId, auth.companyId)
  if (!empId) return null
  // Only branch-scoped 'buyer' assignments restrict visibility here — a
  // company-wide buyer assignment correctly falls through to "no restriction"
  // (null), matching the semantics everywhere else buyer scope is resolved.
  const branches = await query<{ branch_id: string }>(
    `SELECT DISTINCT branch_id FROM po_position_assignments
     WHERE employee_id=$1 AND company_id=$2 AND position='buyer' AND is_active=true AND branch_id IS NOT NULL`,
    [empId, auth.companyId],
  )
  if (branches.rows.length === 0) return null
  return branches.rows.map((r) => r.branch_id)
}

// The one place "can this user view project X" is decided for single-project
// read resolvers (project, projectCompletionBlockers, projectTeamMembers, ...):
// either the company-wide projects.view registry permission, or a direct
// relationship to the project itself (its creator, PM, or an active team
// member) — regardless of that project's status. This intentionally differs
// from the `projects` list query's row filter, which additionally hides
// 'pending' projects from anyone but their creator to keep the general browse
// list decluttered — that's a list-declutter choice, not a real access
// restriction, so it doesn't apply once you already have a project's id (e.g.
// a PM opening a pending project via a direct link should still get in).
// Throws on failure, matching requirePermGW's contract.
async function requireProjectViewGW(
  auth: { userId: string; companyId: string; role: string },
  projectId: string,
): Promise<void> {
  if (isPermissionBypassGW(auth.role)) return
  // Creator always gets in — regardless of status or the projects.view registry
  // grant. Same "you can always find what you made" principle already applied
  // to the project list, and it's what actually needed fixing here.
  const creatorCheck = await query(
    `SELECT 1 FROM projects WHERE id=$1 AND company_id=$2 AND created_by=$3`,
    [projectId, auth.companyId, auth.userId],
  )
  if (creatorCheck.rows[0]) return
  // Otherwise: unchanged from how this worked before — projects.view is a
  // necessary prerequisite but not sufficient on its own; the caller must also
  // be the project's PM or an active team member, and the project must not be
  // pending (pending stays hidden from everyone but its creator).
  await requirePermGW(auth, 'projects.view', 'view')
  const assigned = await query(
    `SELECT 1 FROM projects p
     WHERE p.id=$1 AND p.company_id=$2 AND p.status != 'pending'
       AND (
         p.project_manager_id IN (SELECT id FROM employees WHERE user_id=$3)
         OR EXISTS (
           SELECT 1 FROM project_members pm
           JOIN employees emp ON emp.id=pm.employee_id
           WHERE pm.project_id=p.id AND emp.user_id=$3 AND pm.is_active=true
         )
       )
     LIMIT 1`,
    [projectId, auth.companyId, auth.userId],
  )
  if (!assigned.rows[0]) throw new Error(`Requires 'view' access to 'projects.view'`)
}

// A handful of report/lookup resolvers accept an optional companyId argument
// that overrides the caller's own company (a convenience for admin-facing
// screens). Without this guard any authenticated user could pass an
// arbitrary companyId and read another company's financial/HR data.
// Mirrors the existing userCompanies resolver's system_admin-only rule for
// cross-company access — no separate multi-company grant concept exists
// in this codebase today.
function resolveReportCompanyIdGW(
  auth: { companyId: string; role: string },
  argsCompanyId: string | undefined | null,
): string {
  const cid = argsCompanyId ?? auth.companyId
  if (cid !== auth.companyId && auth.role !== 'system_admin') {
    throw new Error("Forbidden: cannot view another company's data")
  }
  return cid
}

// ── PO notification helpers ──────────────────────────────────────────────────
// Mirror services/procurement/src/lib/po-helpers.ts exactly — that copy is
// unused by the frontend (which calls these GraphQL mutations, not the REST
// routes it backs), so none of the live PO-transition mutations ever notified
// anyone. All 4 just enqueue a service_outbox row for the notifications
// service to actually send.

interface POAuthGWNotification {
  type: string
  title: string
  body: string
}

async function notifyPositionHoldersGW(
  poId: string,
  position: string,
  notification: POAuthGWNotification,
): Promise<void> {
  const poResult = await query(
    `SELECT po.project_id, po.branch_id, ou.id AS organizer_user_id
     FROM purchase_orders po
     LEFT JOIN users ou ON ou.id = po.organizer_id
     WHERE po.id = $1`,
    [poId],
  )
  const po = poResult.rows[0]
  if (!po) return

  const deptResult = await query(
    `SELECT e.department_id FROM employees e WHERE e.user_id = $1 LIMIT 1`,
    [po.organizer_user_id],
  )
  const departmentId = (deptResult.rows[0]?.department_id as string | null) ?? null

  // Company-wide fallback requires ALL scope dimensions to be null on the
  // assignment row — otherwise a branch-only (or project/department-only)
  // assignment would incorrectly match every PO regardless of scope.
  const holders = await query(
    `SELECT DISTINCT u.id AS user_id
     FROM po_position_assignments ppa
     JOIN employees e ON e.id = ppa.employee_id
     JOIN users u ON u.id = e.user_id
     WHERE ppa.position = $1 AND ppa.is_active = true
       AND (
         ($2::uuid IS NOT NULL AND ppa.project_id = $2)
         OR ($3::uuid IS NOT NULL AND ppa.department_id = $3)
         OR ($4::uuid IS NOT NULL AND ppa.branch_id = $4)
         OR (ppa.project_id IS NULL AND ppa.department_id IS NULL AND ppa.branch_id IS NULL)
       )`,
    [position, po.project_id ?? null, departmentId, po.branch_id ?? null],
  )
  for (const holder of holders.rows) {
    await query(
      `INSERT INTO service_outbox (service, event_type, payload) VALUES ('notifications', $1, $2)`,
      [notification.type, JSON.stringify({ userId: holder.user_id, poId, ...notification })],
    )
  }
}

async function notifyUserGW(
  userId: string,
  companyId: string,
  notification: POAuthGWNotification & { poId?: string; poNumber?: string },
): Promise<void> {
  await query(
    `INSERT INTO service_outbox (service, event_type, payload) VALUES ('notifications', $1, $2)`,
    [notification.type, JSON.stringify({ userId, companyId, ...notification })],
  )
}

async function notifyFinanceTeamGW(
  companyId: string,
  notification: POAuthGWNotification & { poId?: string; poNumber?: string },
): Promise<void> {
  const users = await query(
    `SELECT DISTINCT u.id AS user_id
     FROM users u
     JOIN user_company_roles ucr ON ucr.user_id = u.id
     WHERE ucr.company_id = $1
       AND (ucr.role IN ('company_admin', 'system_admin')
            OR (ucr.module = 'finance' AND ucr.role IN ('module_admin', 'module_user')))
       AND u.is_active = true`,
    [companyId],
  )
  for (const user of users.rows) {
    await query(
      `INSERT INTO service_outbox (service, event_type, payload) VALUES ('notifications', $1, $2)`,
      [notification.type, JSON.stringify({ userId: user.user_id, companyId, ...notification })],
    )
  }
}

interface RechargeGWNotification {
  type: string
  title: string
  body: string
  requestId: string
}

async function notifyRechargeUserGW(
  userId: string,
  companyId: string,
  notification: RechargeGWNotification,
): Promise<void> {
  await query(
    `INSERT INTO service_outbox (service, event_type, payload) VALUES ('notifications', $1, $2)`,
    [notification.type, JSON.stringify({ userId, companyId, ...notification })],
  )
}

async function notifyDeptHeadsAndAdminsGW(
  poId: string,
  notification: POAuthGWNotification,
): Promise<void> {
  const poResult = await query(`SELECT po.organizer_id FROM purchase_orders po WHERE po.id = $1`, [
    poId,
  ])
  const organizerId = poResult.rows[0]?.organizer_id as string | undefined
  if (!organizerId) return

  const deptHeads = await query(
    `SELECT DISTINCT u.id AS user_id
     FROM departments d
     JOIN employees mgr ON mgr.id = d.manager_id
     JOIN users u ON u.id = mgr.user_id
     WHERE d.id = (SELECT e.department_id FROM employees e WHERE e.user_id = $1 LIMIT 1)`,
    [organizerId],
  )
  const admins = await query(
    `SELECT DISTINCT u.id AS user_id
     FROM users u
     JOIN user_company_roles ucr ON ucr.user_id = u.id
     WHERE ucr.role = 'system_admin' AND u.is_active = true`,
    [],
  )
  for (const r of [...deptHeads.rows, ...admins.rows]) {
    await query(
      `INSERT INTO service_outbox (service, event_type, payload) VALUES ('notifications', $1, $2)`,
      [notification.type, JSON.stringify({ userId: r.user_id, poId, ...notification })],
    )
  }
}

// Resolves what to multiply an amount in `currencyCode` by to get an amount in
// the PO's base currency. 1 when they already match (the common case, needs no
// configuration); otherwise looks up the company's manually-maintained
// po_fx_rates (Settings → PO Exchange Rates — deliberately not the date-scored
// automated fx_rates/fx_rate_sync tables, which are for finance journal
// revaluation, not this). Throws rather than silently defaulting to 1 for an
// unconfigured currency, since that would understate/overstate the PO total.
async function resolveFxRateToBase(
  client: import('@fnc-erp/db').PoolClient,
  companyId: string,
  currencyCode: string,
  baseCurrencyCode: string,
): Promise<number> {
  if (currencyCode === baseCurrencyCode) return 1
  const r = await client.query<{ rate_to_base: number }>(
    `SELECT rate_to_base FROM po_fx_rates WHERE company_id=$1 AND currency_code=$2`,
    [companyId, currencyCode],
  )
  const rate = r.rows[0]?.rate_to_base
  if (rate == null)
    throw new Error(
      `No PO exchange rate configured for ${currencyCode} → ${baseCurrencyCode}. Set one in Settings → PO Exchange Rates first.`,
    )
  return rate
}

async function recalcPO(client: import('@fnc-erp/db').PoolClient, poId: string): Promise<void> {
  // Each line's total_price is in that line's own currency_code; fx_rate_to_base
  // (set when the line is priced — see submitPOMarketPricing) converts it into
  // the PO's base_currency_code before summing, so the header total is always a
  // real, correctly-converted number even when lines were quoted in different
  // currencies. Lines not yet priced (fx_rate_to_base still NULL) are treated as
  // already-in-base-currency (rate 1) — the common, same-currency case needs no
  // configuration at all.
  await client.query(
    `UPDATE purchase_orders
     SET subtotal=(SELECT COALESCE(SUM(total_price * COALESCE(fx_rate_to_base,1)),0) FROM po_lines WHERE po_id=$1),
         total_amount=(SELECT COALESCE(SUM(total_price * COALESCE(fx_rate_to_base,1)),0) FROM po_lines WHERE po_id=$1),
         updated_at=NOW()
     WHERE id=$1`,
    [poId],
  )
}

