async function planCPM(projectId: string) {
  const actsR = await query(
    `SELECT id, planned_start, planned_finish, duration_days FROM project_activities WHERE project_id=$1 AND planned_start IS NOT NULL`,
    [projectId],
  )
  const depsR = await query(
    `SELECT predecessor_id, successor_id, dependency_type, lag_days FROM project_activity_dependencies WHERE project_id=$1`,
    [projectId],
  )
  interface Node {
    id: string
    es: Date
    ef: Date
    ls: Date | null
    lf: Date | null
    dur: number
  }
  const nodes = new Map<string, Node>()
  for (const a of actsR.rows) {
    const s = new Date(a.planned_start)
    const f = new Date(a.planned_finish)
    nodes.set(String(a.id), {
      id: String(a.id),
      es: s,
      ef: f,
      ls: null,
      lf: null,
      dur: Number(a.duration_days),
    })
  }
  const succs = new Map<string, { to: string; type: string; lag: number }[]>()
  const preds = new Map<string, { from: string; type: string; lag: number }[]>()
  for (const d of depsR.rows) {
    const from = String(d.predecessor_id)
    const to = String(d.successor_id)
    if (!succs.has(from)) succs.set(from, [])
    succs.get(from)!.push({ to, type: String(d.dependency_type), lag: Number(d.lag_days) })
    if (!preds.has(to)) preds.set(to, [])
    preds.get(to)!.push({ from, type: String(d.dependency_type), lag: Number(d.lag_days) })
  }
  // Kahn topological sort
  const inDeg = new Map<string, number>()
  for (const id of nodes.keys()) inDeg.set(id, 0)
  for (const d of depsR.rows)
    inDeg.set(String(d.successor_id), (inDeg.get(String(d.successor_id)) ?? 0) + 1)
  const queue: string[] = []
  for (const [id, deg] of inDeg) if (deg === 0) queue.push(id)
  const topo: string[] = []
  while (queue.length) {
    const n = queue.shift()!
    topo.push(n)
    for (const s of succs.get(n) ?? []) {
      const nd = (inDeg.get(s.to) ?? 1) - 1
      inDeg.set(s.to, nd)
      if (nd === 0) queue.push(s.to)
    }
  }
  // Forward pass
  const addDays = (d: Date, n: number) => {
    const r = new Date(d)
    r.setDate(r.getDate() + n)
    return r
  }
  for (const id of topo) {
    const n = nodes.get(id)
    if (!n) continue
    const myPreds = preds.get(id) ?? []
    if (myPreds.length > 0) {
      let latest = new Date(0)
      for (const p of myPreds) {
        const pn = nodes.get(p.from)
        if (!pn) continue
        const t =
          p.type === 'SS'
            ? addDays(pn.es, p.lag)
            : p.type === 'FF'
              ? addDays(pn.ef, p.lag - n.dur)
              : p.type === 'SF'
                ? addDays(pn.ef, p.lag)
                : addDays(pn.ef, p.lag)
        if (t > latest) latest = t
      }
      n.es = latest
      n.ef = addDays(n.es, n.dur)
    }
  }
  // Backward pass
  let projectEnd = new Date(0)
  for (const n of nodes.values()) if (n.ef > projectEnd) projectEnd = n.ef
  for (const n of nodes.values()) {
    n.ls = null
    n.lf = null
  }
  for (const id of [...topo].reverse()) {
    const n = nodes.get(id)
    if (!n) continue
    const mySuccs = succs.get(id) ?? []
    if (mySuccs.length === 0) {
      n.lf = projectEnd
      n.ls = addDays(projectEnd, -n.dur)
    } else {
      let earliest: Date | null = null
      for (const s of mySuccs) {
        const sn = nodes.get(s.to)
        if (!sn || sn.ls === null) continue
        const t =
          s.type === 'SS'
            ? addDays(sn.ls, -s.lag)
            : s.type === 'FF'
              ? addDays(sn.lf!, -s.lag - n.dur)
              : s.type === 'SF'
                ? addDays(sn.ls, s.lag - n.dur)
                : addDays(sn.ls, -s.lag - n.dur)
        if (earliest === null || t < earliest) earliest = t
      }
      if (earliest !== null) {
        n.ls = earliest
        n.lf = addDays(earliest, n.dur)
      }
    }
  }
  // Write results
  for (const n of nodes.values()) {
    if (n.ls === null) continue
    const tf = Math.round((n.ls.getTime() - n.es.getTime()) / 86400000)
    const isCrit = tf <= 0
    await query(
      `UPDATE project_activities SET early_start=$1, early_finish=$2, late_start=$3, late_finish=$4, total_float=$5, is_critical=$6, updated_at=NOW() WHERE id=$7`,
      [
        n.es.toISOString().slice(0, 10),
        n.ef.toISOString().slice(0, 10),
        n.ls.toISOString().slice(0, 10),
        n.lf!.toISOString().slice(0, 10),
        tf,
        isCrit,
        n.id,
      ],
    )
  }
}

